import{_ as n,H as i,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"04 | RAG索引（二）：分块策略与Embedding技术","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么说分块很重要？","slug":"为什么说分块很重要","link":"#为什么说分块很重要","children":[]},{"level":2,"title":"分块策略","slug":"分块策略","link":"#分块策略","children":[{"level":3,"title":"固定大小分块（Fixed Size Chunking）","slug":"固定大小分块-fixed-size-chunking","link":"#固定大小分块-fixed-size-chunking","children":[]},{"level":3,"title":"重叠分块（Overlap Chunking）","slug":"重叠分块-overlap-chunking","link":"#重叠分块-overlap-chunking","children":[]},{"level":3,"title":"递归分块（Recursive Chunking）","slug":"递归分块-recursive-chunking","link":"#递归分块-recursive-chunking","children":[]},{"level":3,"title":"文档特定分块（Document Specific Chunking）","slug":"文档特定分块-document-specific-chunking","link":"#文档特定分块-document-specific-chunking","children":[]},{"level":3,"title":"语义分块（Semantic Chunking）","slug":"语义分块-semantic-chunking","link":"#语义分块-semantic-chunking","children":[]},{"level":3,"title":"混合分块（Mix Chunking）","slug":"混合分块-mix-chunking","link":"#混合分块-mix-chunking","children":[]}]},{"level":2,"title":"分块策略实战","slug":"分块策略实战","link":"#分块策略实战","children":[]},{"level":2,"title":"什么是 Embedding 嵌入？","slug":"什么是-embedding-嵌入","link":"#什么是-embedding-嵌入","children":[]},{"level":2,"title":"Embedding Model 嵌入模型","slug":"embedding-model-嵌入模型","link":"#embedding-model-嵌入模型","children":[]},{"level":2,"title":"Embedding Model 嵌入模型评估","slug":"embedding-model-嵌入模型评估","link":"#embedding-model-嵌入模型评估","children":[]},{"level":2,"title":"Embedding Model 技术实战","slug":"embedding-model-技术实战","link":"#embedding-model-技术实战","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"RAG快速开发实战/04｜RAG索引（二）：分块策略与Embedding技术.md","filePath":"RAG快速开发实战/04｜RAG索引（二）：分块策略与Embedding技术.md","lastUpdated":1795533570000}'),s={name:"RAG快速开发实战/04｜RAG索引（二）：分块策略与Embedding技术.md"};function p(l,e,r,o,h,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="_04-rag索引-二-分块策略与embedding技术" tabindex="-1">04 | RAG索引（二）：分块策略与Embedding技术 <a class="header-anchor" href="#_04-rag索引-二-分块策略与embedding技术" aria-label="Permalink to &quot;04 | RAG索引（二）：分块策略与Embedding技术&quot;">​</a></h1><ul><li>本门课程为精品小课，不标配音频</li></ul><p>你好，我是常扬。</p><p>本节课将深入探讨 RAG 索引（Indexing）流程中的分块（Chunking）策略和嵌入（Embedding）技术。</p><p>文档数据（Documents）经过解析后，通过分块技术将信息内容划分为适当大小的文档片段（chunks），从而使 RAG 系统能够高效处理和精准检索这些片段信息。分块的本质在于依据一定逻辑或语义原则，将较长文本拆解为更小的单元。分块策略有多种，各有侧重，选择适合特定场景的分块策略是提升 RAG 系统召回率的关键。</p><p>嵌入模型（Embedding Model）负责将文本数据映射到高维向量空间中，将输入的文档片段转换为对应的嵌入向量（embedding vectors）。这些向量捕捉了文本的语义信息，并被存储在向量库（VectorStore）中，以便后续检索使用。用户查询（Query）同样通过嵌入模型的处理生成查询嵌入向量，这些向量用于在向量数据库中通过向量检索（Vector Retrieval）匹配最相似的文档片段。根据不同的场景需求，评估并选择最优的嵌入模型，以确保 RAG 的检索性能符合要求。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/1.png" alt=""></a></p><h2 id="为什么说分块很重要" tabindex="-1">为什么说分块很重要？ <a class="header-anchor" href="#为什么说分块很重要" aria-label="Permalink to &quot;为什么说分块很重要？&quot;">​</a></h2><p>文档通常包含丰富的上下文信息和复杂的语义结构，通过将文档分块，模型可以更有效地提取关键信息，并减少不相关内容的干扰。分块的目标在于确保每个片段在保留核心语义的同时，具备相对独立的语义完整性，从而使模型在处理时不必依赖广泛的上下文信息，增强检索召回的准确性。</p><p>分块的重要性在于它直接影响 RAG 系统的生成质量。首先，合理的分块能够确保检索到的片段与用户查询信息高度匹配，避免信息冗余或丢失。其次，分块有助于提升生成内容的连贯性，精心设计的独立语义片段可以降低模型对上下文的依赖，从而增强生成的逻辑性与一致性。最后，分块策略的选择还会影响系统的响应速度与效率，模型能够更快、更准确地处理和生成内容。</p><p>分块策略最大的挑战在于确定分块的大小。如果片段过大，可能导致向量无法精确捕捉内容的特定细节并且计算成本增加；若片段过小，则可能丢失上下文信息，导致句子碎片化和语义不连贯。较小的块适用于需要细粒度分析的任务，例如情感分析，能够精确捕捉特定短语或句子的细节。更大的块则更为合适需要保留更广泛上下文的场景，例如文档摘要或主题检测。因此，块大小的确定必须在计算效率和上下文信息之间取得平衡。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/2.png" alt=""></a></p><h2 id="分块策略" tabindex="-1">分块策略 <a class="header-anchor" href="#分块策略" aria-label="Permalink to &quot;分块策略&quot;">​</a></h2><p>最佳的分块策略取决于具体的应用场景，而非行业内的统一标准。根据场景中文档内容的特点和查询问题的需求，选择最合适该场景的分块策略，以确保 RAG 系统中大模型能够更精确地处理和检索数据。</p><p>多种分块策略从本质上来看，由以下三个关键组成部分构成：</p><ol><li><p>大小：每个文档块所允许的最大字符数。</p></li><li><p>重叠：在相邻数据块之间，重叠字符的数量。</p></li><li><p>拆分：通过段落边界、分隔符、标记，或语义边界来确定块边界的位置。</p></li></ol><p>上述三个组成部分共同决定了分块策略的特性及其适用场景。基于这些组成部分，常见的分块策略包括：固定大小分块（Fixed Size Chunking）、重叠分块（Overlap Chunking）、递归分块（Recursive Chunking）、文档特定分块（Document Specific Chunking）、语义分块（Semantic Chunking）、混合分块（Mix Chunking）。下面我将对这些策略逐一进行介绍。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/3.png" alt=""></a></p><h3 id="固定大小分块-fixed-size-chunking" tabindex="-1">固定大小分块（Fixed Size Chunking） <a class="header-anchor" href="#固定大小分块-fixed-size-chunking" aria-label="Permalink to &quot;固定大小分块（Fixed Size Chunking）&quot;">​</a></h3><p>最基本的方法是将文档按固定大小进行分块，通常作为分块策略的基准线使用。</p><p>Chunk Size 100 字符（每种颜色为一个文本块，Chunk 切分可视化呈现链接：<a href="https://chunkviz.up.railway.app/%EF%BC%89" target="_blank" rel="noreferrer">https://chunkviz.up.railway.app/）</a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/4.png" alt=""></a></p><p>Chunk Size 50 字符</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/5.png" alt=""></a></p><p>适用场景</p><ol><li><p>作为分块策略的基准线；</p></li><li><p>对大型数据集进行初步分析；</p></li><li><p>实现简单且可预测性高，分块便于管理；</p></li><li><p>适用于格式和大小相似的同质数据集，如新闻文章或博客文章。</p></li></ol><p>问题</p><ol><li><p>不考虑内容上下文，可能在句子或段落中断内容，导致无意义的文本块，例如上面图示中的“大模 / 型”“边际成 / 本”等词组被中断；</p></li><li><p>缺乏灵活性，无法适应文本的自然结构。</p></li></ol><h3 id="重叠分块-overlap-chunking" tabindex="-1">重叠分块（Overlap Chunking） <a class="header-anchor" href="#重叠分块-overlap-chunking" aria-label="Permalink to &quot;重叠分块（Overlap Chunking）&quot;">​</a></h3><p>通过滑动窗口技术切分文本块，使新文本块与前一个块的内容部分重叠，从而保留块边界处的重要上下文信息，增强系统的语义相关性。虽然这种方法增加了存储需求和冗余信息，但它有效避免了在块之间丢失关键语义或句法结构。</p><p>Chunk Size 100 字符，Chunk overlap 20 字符（绿色）</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/6.png" alt=""></a></p><p>适用场景</p><ol><li><p>需要深入理解语义并保持上下文完整性的文档，如法律文档、技术手册或科研论文；</p></li><li><p>提升分块内容的连贯性，以提高分析质量。</p></li></ol><p>问题</p><ol><li><p>计算复杂度增加，处理效率降低；</p></li><li><p>冗余信息的存储和管理成为负担。</p></li></ol><h3 id="递归分块-recursive-chunking" tabindex="-1">递归分块（Recursive Chunking） <a class="header-anchor" href="#递归分块-recursive-chunking" aria-label="Permalink to &quot;递归分块（Recursive Chunking）&quot;">​</a></h3><p>通过预定义的文本分隔符（如换行符\\n\\n、\\n ，句号、逗号、感叹号、空格等）迭代地将文本分解为更小的块，以实现段大小的均匀性和语义完整性。此过程中，文本首先按较大的逻辑单元分割（如段落 \\n\\n），然后逐步递归到较小单元（如句子 \\n 和单词），确保在分块大小限制内保留最强的语义片段。</p><p>Chunk Size 100 字符</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/7.png" alt=""></a></p><p>这种方法适用于需要逐层分析的文本文档或需要分解成长片段、长段落的长文档，如研究报告、法律文档等。不过仍有可能在块边界处模糊语义，容易将完整的语义单元切分开。</p><h3 id="文档特定分块-document-specific-chunking" tabindex="-1">文档特定分块（Document Specific Chunking） <a class="header-anchor" href="#文档特定分块-document-specific-chunking" aria-label="Permalink to &quot;文档特定分块（Document Specific Chunking）&quot;">​</a></h3><p>根据文档的格式（如 Markdown、Latex、或编程语言如 Python 等）进行定制化分割的技术。此方法依据文档的特定格式和结构规则，例如 Markdown 的标题、列表项，或 Python 代码中的函数和类定义等，来确定分块边界。通过这种方式，确保分块能够准确反映文档的格式特点，优化保留这些语义完整的单元，提升后续的处理和分析效果。</p><p>Chunk Size 100 字符，Markdown 特定分块</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/8.png" alt=""></a></p><p>Chunk Size 100 字符，Python 特定分块</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/9.png" alt=""></a></p><p>这种方法可以根据特定的文档结构，进行准确的语义内容切分，在编程语言、Markdown、Latex 等结构文档中表现出色。但文档特定分块的方式格式依赖性强，不同格式之间的分块策略不通用，并且无法处理格式不规范及混合多种格式的情况。</p><h3 id="语义分块-semantic-chunking" tabindex="-1">语义分块（Semantic Chunking） <a class="header-anchor" href="#语义分块-semantic-chunking" aria-label="Permalink to &quot;语义分块（Semantic Chunking）&quot;">​</a></h3><p>基于文本的自然语言边界（如句子、段落或主题中断）进行分段的技术，需要使用 NLP 技术根据语义分词分句，旨在确保每个分块都包含语义连贯的信息单元。语义分块保留了较高的上下文保留，并确保每个块都包含连贯的信息，但需要更多的计算资源。常用的分块策略有spaCy 和 NLTK 的 NLP 库，spaCy 适用于需要高效、精准语义切分的大规模文本处理，NLTK 更适合教学、研究和需要灵活自定义的语义切分任务。</p><p>spaCy 语义分块</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/10.png" alt=""></a></p><p>适用场景</p><ol><li><p>确保每个文档块的信息完整且语义连贯；</p></li><li><p>提高检索结果的相关性和准确性；</p></li><li><p>适用于复杂文档和上下文敏感的精细化分析。</p></li></ol><p>问题</p><ol><li><p>需要额外的高计算资源，特别是在处理大型或动态变化的文档数据时；</p></li><li><p>处理效率降低。</p></li></ol><h3 id="混合分块-mix-chunking" tabindex="-1">混合分块（Mix Chunking） <a class="header-anchor" href="#混合分块-mix-chunking" aria-label="Permalink to &quot;混合分块（Mix Chunking）&quot;">​</a></h3><p>混合分块是一种结合多种分块方法的技术，通过综合利用不同分块技术的优势，提高分块的精准性和效率。例如，在初始阶段使用固定长度分块快速整理大量文档，而在后续阶段使用语义分块进行更精细的分类和主题提取。根据实际业务场景，设计多种分块策略的混合，能够灵活适应各种需求，提供更强大的分块方案。</p><p>适用场景</p><ol><li><p>适用于多层次的精细化分块场景；</p></li><li><p>数据集动态变化，包含多种文档格式与结构；</p></li><li><p>平衡处理速度与准确性的场景。</p></li></ol><p>问题</p><ol><li><p>实现复杂度高；</p></li><li><p>策略调优难度高；</p></li><li><p>资源消耗增加。</p></li></ol><h2 id="分块策略实战" tabindex="-1">分块策略实战 <a class="header-anchor" href="#分块策略实战" aria-label="Permalink to &quot;分块策略实战&quot;">​</a></h2><p>LangChain 提供了多种文档分块方法（Text Splitters），帮助开发者轻松集成使用。上述分块策略在 langchain_text_splitters 库中对应的具体方法类如下：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/11.png" alt=""></a></p><p>除了上述方法类外，LangChain 还提供了更多的 Text Splitter，参考 LangChain 官网。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关于开发环境以及 langchain 和 langchain_community 等库的安装和配置，已在第 02</span></span></code></pre></div><p>课中详细说明。下面实战的代码更新在 Gitee 托管项目的 rag_app_lesson4.py 代码文件中，rag_app_lesson4.py 代码基于第 03 讲中的 rag_app_lesson3.py 进行迭代更新。</p><p>SpacyTextSplitter 和 NLTKTextSplitter 需要额外安装 Python 依赖库，其中 SpacyTextSplitter还需要按照文档的语言对应安装额外的语言模型。</p><p>命令行中执行以下安装命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source rag_env/bin/activate  # 激活虚拟环境</span></span>
<span class="line"><span>pip install spacy nltk -i https://pypi.tuna.tsinghua.edu.cn/simple</span></span>
<span class="line"><span>python -m spacy download zh_core_web_sm # 如果需要进行中文分块，安装spacy中文语言模型</span></span>
<span class="line"><span>python -m spacy download en_core_web_sm # 如果需要进行英文分块，安装spacy英文语言模型</span></span></code></pre></div><p>导入 langchain.text_splitter 中各种文档分块类代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from langchain.text_splitter import (</span></span>
<span class="line"><span>   CharacterTextSplitter,</span></span>
<span class="line"><span>   RecursiveCharacterTextSplitter,</span></span>
<span class="line"><span>   MarkdownTextSplitter,</span></span>
<span class="line"><span>   PythonCodeTextSplitter,</span></span>
<span class="line"><span>   LatexTextSplitter,</span></span>
<span class="line"><span>   SpacyTextSplitter,</span></span>
<span class="line"><span>   NLTKTextSplitter</span></span>
<span class="line"><span>) # 从 langchain.text_splitter 模块中导入各种文档分块类</span></span></code></pre></div><p>CharacterTextSplitter、RecursiveCharacterTextSplitter、MarkdownTextSplitter、PythonCodeTextSplitter、LatexTextSplitter、NLTKTextSplitter 替换原有 text_splitter 参数的赋值类即可。需要额外处理的是 SpacyTextSplitter，需要参数 pipeline 指定具体的语言模型才可以运行。</p><p>indexing_process 方法中切分文本块库代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 配置SpacyTextSplitter分割文本块库</span></span>
<span class="line"><span>#text_splitter = SpacyTextSplitter(</span></span>
<span class="line"><span>#    chunk_size=512, chunk_overlap=128, pipeline=&quot;zh_core_web_sm&quot;)</span></span>
<span class="line"><span># 配置RecursiveCharacterTextSplitter分割文本块</span></span>
<span class="line"><span># 可以更换为CharacterTextSplitter、MarkdownTextSplitter、PythonCodeTextSplitter、Lat</span></span>
<span class="line"><span>text_splitter = RecursiveCharacterTextSplitter(</span></span>
<span class="line"><span>chunk_size=512, chunk_overlap=128)</span></span></code></pre></div><p>其中，SpacyTextSplitter 的文本分块逻辑已被注释。如果需要使用，只需取消注释，并将下方使用其他文本分块库的代码注释即可。</p><h2 id="什么是-embedding-嵌入" tabindex="-1">什么是 Embedding 嵌入？ <a class="header-anchor" href="#什么是-embedding-嵌入" aria-label="Permalink to &quot;什么是 Embedding 嵌入？&quot;">​</a></h2><p>Embedding 嵌入是指将文本、图像、音频、视频等形式的信息映射为高维空间中的密集向量表示。这些向量在语义空间中起到坐标的作用，捕捉对象之间的语义关系和隐含的意义。通过在向量空间中进行计算（例如余弦相似度），可以量化和衡量这些对象之间的语义相似性。</p><p>在具体实现中，嵌入的每个维度通常对应文本的某种特征，例如性别、类别、数量等。通过多维度的数值表示，计算机能够理解并解析文本的复杂语义结构。例如，“man”和“woman”在描述性别维度上具有相似性，而“king”和“queen”则在性别和王室身份等维度上表现出相似的语义特征。</p><p>向量是一组在高维空间中定义点的数值数组，而嵌入则是将信息（如文本）转化为这种向量表示的过程。这些向量能够捕捉数据的语义及其他重要特征，使得语义相近的对象在向量空间中彼此邻近，而语义相异的对象则相距较远。向量检索（Vector Retrieval）是一种基于向量表示的搜索技术，通过计算查询向量与已知文本向量的相似度来识别最相关的文本数据。向量检索的高效性在于，它能在大规模数据集中快速、准确地找到与查询最相关的内容，这得益于向量表示中蕴含的丰富语义信息。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/12.png" alt=""></a></p><h2 id="embedding-model-嵌入模型" tabindex="-1">Embedding Model 嵌入模型 <a class="header-anchor" href="#embedding-model-嵌入模型" aria-label="Permalink to &quot;Embedding Model 嵌入模型&quot;">​</a></h2><p>自 2013 年以来，word2vec、GloVe、fastText 等嵌入模型通过分析大量文本数据，学习得出单词的嵌入向量。近年来，随着 transformer 模型的突破，嵌入技术以惊人的速度发展。BERT、RoBERTa、ELECTRA 等模型将词嵌入推进到上下文敏感的阶段。这些模型在为文本中的每个单词生成嵌入时，会充分考虑其上下文环境，因此同一个单词在不同语境下的嵌入向量可以有所不同，从而大大提升了模型理解复杂语言结构的能力。</p><p>在 RAG 系统中，Embedding Model 嵌入模型扮演着关键角色，负责将文本数据映射到高维向量空间，以便高效检索和处理。具体而言，Embedding Model 将输入的文档片段（Chunks）和查询文本（Query）转换为嵌入向量（Vectors），这些向量捕捉了文本的语义信息，并可在向量空间中与其他嵌入向量进行比较。</p><p>在 RAG 流程中，文档首先被分割成多个片段，每个片段随后通过 Embedding Model 进行嵌入处理。生成的文档嵌入向量被存储在 VectorStore 中，供后续检索使用。用户查询会通过Embedding Model 转换为查询嵌入向量，这些向量用于在向量数据库中匹配最相似的文档片段，最终组合生成指令（Prompt），大模型生成回答。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/13.png" alt=""></a></p><p>正如图中所示，嵌入模型是 RAG 流程的核心。既然如此重要，市面上有非常多的嵌入模型，我们该如何为我们的业务场景选择最合适的嵌入模型呢？</p><h2 id="embedding-model-嵌入模型评估" tabindex="-1">Embedding Model 嵌入模型评估 <a class="header-anchor" href="#embedding-model-嵌入模型评估" aria-label="Permalink to &quot;Embedding Model 嵌入模型评估&quot;">​</a></h2><p>在选择适合的嵌入模型时，需要综合考虑多个因素，包括特定领域的适用性、检索精度、支持的语言、文本块长度、模型大小以及检索效率等因素。同时以广泛受到认可的 MTEB（Massive Text Embedding Benchmark）和 C-MTEB（Chinese Massive Text EmbeddingBenchmark）榜单作为参考，通过涵盖分类、聚类、语义文本相似性、重排序和检索等多个数据集的评测，开发者可以根据不同任务的需求，评估并选择最优的向量模型，以确保在特定应用场景中的最佳性能。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/14.png" alt=""></a></p><p>MTEB &amp; C-MTEB 榜单</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/RAG%E5%BF%AB%E9%80%9F%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/04/15.png" alt=""></a></p><p>榜单每日更新，上图展示的是 2024 年 8 月 28 日的榜单。点击“Overall”，切换语言为Chinese，可以看到中文嵌入模型的排名。由于 RAG 是一项检索任务，我们需要按“RetrievalAverage”（检索平均值）列对排行榜进行排序，图中显示的就是检索任务效果排序后的结果。在检索任务中，我们需要在榜单顶部看到最佳的检索模型，并且专注于以下几个关键列：</p><ul><li><p>Retrieval Average 检索平均值：较高的检索平均值表示模型更擅长在检索结果列表中将相关项目排在较高的位置，检索效果更好。</p></li><li><p>Model Size 模型大小：模型的大小（以 GB 为单位）。虽然检索性能随模型大小而变化，但要注意，模型大小也会对延迟产生直接影响。因此，在选择模型时，建议筛选掉那些在硬件资源有限的情况下不可行的过大模型。在生产环境中，性能与效率之间的权衡尤为重要。</p></li><li><p>Max Tokens 最大 Token 数：可压缩到单个文本块中的最大 Token 数。因为文档块我们希望不要过大而降低目标信息块的精准度，因此，即使最大 tokens 数为 512 的模型在大部分场景下也足够使用。</p></li><li><p>Embedding Dimensions：嵌入向量的维度。越少的嵌入维度提供更快的推理速度，存储效率更高，而更多的维度可以捕获数据中的细微特征。我们需要在模型的性能和效率之间取得良好的权衡。</p></li><li><p>实验至关重要，在排行榜上表现良好的模型不一定在你的任务上表现良好，试验各种高得分的模型至关重要。我们参考 MTEB 排行榜，选择多个适合我们场景的嵌入模型作为备选，并在我们的业务场景数据集上进行评估测试，以选出最适合我们 RAG 系统的嵌入模型。</p></li></ul><h2 id="embedding-model-技术实战" tabindex="-1">Embedding Model 技术实战 <a class="header-anchor" href="#embedding-model-技术实战" aria-label="Permalink to &quot;Embedding Model 技术实战&quot;">​</a></h2><p>我们使用 SentenceTransformers 作为加载嵌入模型的 Python 模块。</p><p>SentenceTransformers（又名 SBERT）是一个用于训练和推理文本嵌入模型的 Python 模块，可以在 RAG 系统中计算嵌入向量。使用 SentenceTransformers 进行文本嵌入转换非常简单：只需导入模块库、加载模型，并调用 encode 方法即可。执行时，SentenceTransformers 会自动下载相应的模型库，当然也可以手动下载并指定模型库的路径。所有可用的模型都可以在 SentenceTransformers 模型库 查看，超过 8000 个发布在Hugging Face 上的嵌入模型库可以被使用。</p><p>在中文领域，智源研究院的 BGE 系列模型 是较为知名的开源嵌入模型，在 C-MTEB 上表现出色。BGE 系列目前包含 23 个嵌入模型，涵盖多种维度、多种最大 Token 数和模型大小，用户可以根据需求进行测试和使用。</p><p>load_embedding_model 方法中使用 SentenceTransformer 加载嵌入模型代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 绝对路径：SentenceTransformer读取绝对路径下的bge-small-zh-v1.5模型，如需使用其他模型，下</span></span>
<span class="line"><span>embedding_model = SentenceTransformer(os.path.abspath(&#39;rag_app/bge-small-zh-v1.5&#39;</span></span>
<span class="line"><span># 自动下载：SentenceTransformer库自动下载BAAI/bge-large-zh-v1.5模型，如需下载其他模型，输</span></span>
<span class="line"><span># embedding_model = SentenceTransformer(&#39;BAAI/bge-large-zh-v1.5&#39;)</span></span></code></pre></div><p>indexing_process 方法中将文本转化为嵌入向量代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 文本块转化为嵌入向量列表，normalize_embeddings表示对嵌入向量进行归一化，用于后续流程准确计算</span></span>
<span class="line"><span>embeddings = []</span></span>
<span class="line"><span>for chunk in all_chunks:</span></span>
<span class="line"><span>     embedding = embedding_model.encode(chunk, normalize_embeddings=True)</span></span>
<span class="line"><span>     embeddings.append(embedding)</span></span></code></pre></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们深入探讨了 RAG 索引流程中的分块策略和嵌入技术。</p><p>分块策略通过将文档拆分为更小的片段，使模型能更高效地处理和检索信息，确保每个片段在保留核心语义的同时，具备相对独立的语义完整性。常见的分块策略包括固定大小分块、重叠分块、递归分块、文档特定分块、语义分块、混合分块。分块的关键在于选择适合的分块大小与特定场景的策略，以优化系统的检索精度和生成内容的连贯性。</p><p>嵌入技术将文本数据映射到高维向量空间中，捕捉其语义信息，支持向量检索，从而在大规模数据中快速识别与查询最相关的文档片段。在选择嵌入模型时，需要综合考虑特定领域的适用性、检索精度、支持的语言、文本块长度、模型大小以及检索效率等因素。</p><p>通过参考 MTEB 和 C-MTEB 的评测榜单，可以评估多个高得分的模型，并在具体的业务场景中进行测试，最终选择最适合该场景的嵌入模型。同时，使用 SentenceTransformers Python模块可以简化嵌入模型的加载和嵌入计算，进而高效率集成测试。</p><p>相关代码已公开在Gitee 代码仓库中了，代码文件为 rag_app_lesson4.py。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>本节课程涵盖了分块策略和嵌入技术两个关键知识点。对应这两个知识点，我给你留两道思考题。</p><ol><li><p>在你的业务场景中，是否曾遇到过因分块策略选择不当而导致检索精度下降的问题？如果有，请分析这个问题，并思考如何通过调整分块策略来优化系统的性能。</p></li><li><p>在选择嵌入模型时，你如何在模型大小与延迟、精度与效率之间做出权衡？分享你在实际项目中平衡这些因素的经验，或探讨在不同业务场景下的最佳平衡点。</p></li></ol><p>欢迎你把你的经验和思考分享到留言区，和我一起讨论，也欢迎你把这节课的内容分享给需要的朋友，我们下节课再见！</p>`,113)])])}const E=n(s,[["render",p]]);export{d as __pageData,E as default};
